\newcommand{\myHexPrism}[5]{
	\begin{scope}[scale=#5]
	    \def\StartAngle{5}	
    	\pgfmathsetmacro{\alpha}{360/6};  

		\coordinate (A0) at (#1,0);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+1*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+1*\alpha)/3};
		\coordinate (A1) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+2*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+2*\alpha)/3};
		\coordinate (A2) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+3*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+3*\alpha)/3};
		\coordinate (A3) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+4*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+4*\alpha)/3};
		\coordinate (A4) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+5*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+5*\alpha)/3};
		\coordinate (A5) at (\xc,\yc);

		\coordinate (A0') at (#1,-#2);
            \pgfmathsetmacro{\xc}{#1*cos(\StartAngle+1*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+1*\alpha)/3};
		\coordinate (A1') at (\xc,-#2+\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+2*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+2*\alpha)/3};
		\coordinate (A2') at (\xc,-#2+\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+3*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+3*\alpha)/3};
		\coordinate (A3') at (\xc,-#2+\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+4*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+4*\alpha)/3};
		\coordinate (A4') at (\xc,-#2+\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+5*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+5*\alpha)/3};
		\coordinate (A5') at (\xc,-#2+\yc);


		% Faces
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A0,A1,A1',A0')
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A1,A2,A2',A1')
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A2,A3,A3',A2')
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A3,A4,A4',A3')
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A4,A0,A0',A4')

		% Base
		\tkzDrawPolygon[draw=none, fill=#3!25, fill opacity=#4](A0,A1,A2,A3,A4,A5)
        % top
		\tkzDrawPolygon[draw=none, fill=#3!25, fill opacity=#4](A0',A1',A2',A3',A4',A5')

		% Edges
		\tkzDrawSegments[thin, color=#3, dashed, opacity=0.75](A1,A1' A2,A2')		
		\tkzDrawSegments[very thick, color=#3](A0,A1 A1,A2 A2,A3 A3,A4 A4,A5 A5,A0)

        \tkzDrawSegments[very thick, color=#3](A0',A0 A3,A3' A4,A4' A5,A5')

		\tkzDrawSegments[very thick, color=#3](A3',A4' A4',A5' A5',A0')
		\tkzDrawSegments[thin, color=#3, dashed, opacity=0.75](A0',A1' A1',A2' A2',A3')   

%		\tkzLabelPoints[above](A0,A1,A2,A3,A4,A5,A0',A1',A2',A3',A4',A5');
	\end{scope}
}

